#!/usr/bin/env bash
#
# Build a signed macOS development acceptance package for hs-server.
#
# This is not a release packager. It exists so the development-only
# macos-dev-install compile feature can be exercised end to end on a disposable
# macOS CI runner. The signing key is generated by CI, kept outside the package,
# and its public half is pinned into the binary at compile time.
#
# Usage:
#   package-macos-development.sh BINARY VERSION PLATFORM SIGNING_KEY OUTPUT_DIR
#
# PLATFORM is macos-arm64 or macos-x86_64. OUTPUT_DIR must not exist.
# Prints `verification_key_hex=<64 hex chars>` on stdout.

set -euo pipefail

usage() {
	cat <<EOF
Usage: ${0##*/} BINARY VERSION PLATFORM SIGNING_KEY OUTPUT_DIR

Create a signed development macOS package containing exactly
artifacts/hs-server, manifest.json, and manifest.sig.
PLATFORM must be macos-arm64 or macos-x86_64.
SIGNING_KEY must be an owner-private Ed25519 private PEM file.
OUTPUT_DIR must not already exist; its parent must exist.
Prints verification_key_hex=<64 hex chars>.
EOF
}

die() {
	printf 'Error: %s\n' "$1" >&2
	exit 1
}

if [[ "$#" -eq 1 && ( "$1" == "-h" || "$1" == "--help" ) ]]; then
	usage
	exit 0
fi
if [[ "$#" -ne 5 ]]; then
	usage >&2
	exit 2
fi

binary_input=$1
version=$2
platform=$3
key_input=$4
output_input=$5
[[ -n "$binary_input" && -n "$version" && -n "$platform" && -n "$key_input" && -n "$output_input" ]] || die "all arguments are required"
[[ "$version" =~ ^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$ ]] || die "version must be strict major.minor.patch"
[[ "$platform" == "macos-arm64" || "$platform" == "macos-x86_64" ]] || die "platform must be macos-arm64 or macos-x86_64"
[[ ! -L "$binary_input" && -f "$binary_input" && -x "$binary_input" ]] || die "binary must be an executable regular non-symlink file"
[[ ! -L "$key_input" && -f "$key_input" ]] || die "signing key must be a regular non-symlink file"
[[ ! -e "$output_input" && ! -L "$output_input" ]] || die "output directory already exists"

command -v python3 >/dev/null 2>&1 || die "python3 is required"
openssl_bin=${HELICOID_OPENSSL:-openssl}
command -v "$openssl_bin" >/dev/null 2>&1 || die "OpenSSL 3 with Ed25519 support is required (set HELICOID_OPENSSL)"

script_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
repo_root=$(cd -- "$script_dir/.." && pwd -P)
output_parent=$(cd -- "$(dirname -- "$output_input")" && pwd -P)
output_dir=$output_parent/$(basename -- "$output_input")
[[ ! -e "$output_dir" && ! -L "$output_dir" ]] || die "output directory already exists"
[[ -d "$output_parent" && ! -L "$output_parent" ]] || die "output parent must be an existing non-symlink directory"

python3 - "$key_input" "$output_parent" <<'PY'
import os
import stat
import sys

key_path = sys.argv[1]
parent = sys.argv[2]

key = os.lstat(key_path)
if not stat.S_ISREG(key.st_mode) or key.st_nlink != 1:
    raise SystemExit("signing key must be a single-link regular file")
if key.st_mode & 0o077:
    raise SystemExit("signing key must not be readable or writable by group or others")

parent_stat = os.lstat(parent)
if not stat.S_ISDIR(parent_stat.st_mode):
    raise SystemExit("output parent is not a directory")
if parent_stat.st_mode & 0o022 and not parent_stat.st_mode & stat.S_ISVTX:
    raise SystemExit("output parent must not be group- or world-writable unless sticky")
PY

temp_dir=$(mktemp -d "$output_parent/.helicoid-macos-package.XXXXXXXX") || die "cannot create package staging directory"
verify_der=$(mktemp "$output_parent/.helicoid-macos-pubkey.XXXXXXXX") || die "cannot create public key staging file"

cleanup() {
	if [[ -n "${temp_dir:-}" && -d "${temp_dir:-}" ]]; then
		rm -rf -- "$temp_dir"
	fi
	rm -f -- "${verify_der:-}"
}
trap cleanup EXIT
trap 'exit 128' HUP INT TERM

mkdir -m 0755 "$temp_dir/artifacts"

python3 - "$binary_input" "$temp_dir/artifacts/hs-server" "$version" "$platform" \
	"$repo_root/src/db.rs" "$repo_root/src/installer/manifest.rs" "$temp_dir/manifest.json" <<'PY'
import hashlib
import json
import os
import re
import stat
import sys
from pathlib import Path

binary = Path(sys.argv[1])
destination = Path(sys.argv[2])
version = sys.argv[3]
platform = sys.argv[4]
database_source = Path(sys.argv[5])
installer_source = Path(sys.argv[6])
manifest_path = Path(sys.argv[7])

def source_integer(path: Path, name: str) -> int:
    contents = path.read_text(encoding="utf-8")
    matches = re.findall(rf"^(?:pub )?const {re.escape(name)}: (?:i64|i32|usize|u32) = ([1-9][0-9]*);$", contents, re.MULTILINE)
    if len(matches) != 1:
        raise SystemExit(f"expected exactly one integer {name} constant in {path}")
    return int(matches[0])

def source_version(path: Path, name: str) -> str:
    contents = path.read_text(encoding="utf-8")
    matches = re.findall(rf'^(?:pub )?const {re.escape(name)}: &str = "([0-9]+\.[0-9]+\.[0-9]+)";$', contents, re.MULTILINE)
    if len(matches) != 1:
        raise SystemExit(f"expected exactly one version {name} constant in {path}")
    return matches[0]

if not re.fullmatch(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", version):
    raise SystemExit("version must be strict major.minor.patch")

source = os.open(binary, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0))
try:
    before = os.fstat(source)
    if not stat.S_ISREG(before.st_mode):
        raise SystemExit("binary is not a regular file")
    if before.st_size <= 0 or before.st_size > 512 * 1024 * 1024:
        raise SystemExit("binary size is outside the package bounds")
    digest = hashlib.sha256()
    copied = 0
    with os.fdopen(os.dup(source), "rb") as reader, destination.open("xb") as writer:
        while True:
            chunk = reader.read(64 * 1024)
            if not chunk:
                break
            copied += len(chunk)
            if copied > 512 * 1024 * 1024:
                raise SystemExit("binary exceeds the package size bound")
            digest.update(chunk)
            writer.write(chunk)
        writer.flush()
        os.fchmod(writer.fileno(), 0o755)
        os.fsync(writer.fileno())
    after = os.fstat(source)
    if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
        raise SystemExit("binary changed while packaging")
finally:
    os.close(source)

if copied != before.st_size:
    raise SystemExit("copied binary size does not match the source")

manifest = {
    "format_version": 1,
    "product": "hs-server",
    "version": version,
    "platform": platform,
    "min_schema_version": source_integer(database_source, "SCHEMA_VERSION"),
    "min_installer_version": source_version(installer_source, "INSTALLER_VERSION"),
    "artifacts": [
        {
            "path": "artifacts/hs-server",
            "sha256": digest.hexdigest(),
            "size_bytes": copied,
        }
    ],
}
manifest_path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
os.chmod(manifest_path, 0o644)
PY

"$openssl_bin" pkeyutl -sign -rawin -inkey "$key_input" -in "$temp_dir/manifest.json" -out "$temp_dir/manifest.sig" \
	|| die "manifest signing failed"
[[ "$(wc -c < "$temp_dir/manifest.sig" | tr -d ' ')" == "64" ]] || die "Ed25519 signature must be exactly 64 bytes"
chmod 0644 "$temp_dir/manifest.json" "$temp_dir/manifest.sig"

"$openssl_bin" pkey -in "$key_input" -pubout -outform DER -out "$verify_der" \
	|| die "cannot derive the Ed25519 public key"
[[ "$(wc -c < "$verify_der" | tr -d ' ')" == "44" ]] || die "Ed25519 public key DER must be 44 bytes"
verify_key_hex=$(python3 - "$verify_der" <<'PY'
import sys
from pathlib import Path
raw = Path(sys.argv[1]).read_bytes()
if len(raw) != 44 or raw[:12] != bytes.fromhex("302a300506032b6570032100"):
    raise SystemExit("unexpected Ed25519 SubjectPublicKeyInfo")
print(raw[-32:].hex())
PY
) || die "cannot extract the Ed25519 public key"
[[ "$verify_key_hex" =~ ^[0-9a-f]{64}$ ]] || die "public key hex is malformed"

"$openssl_bin" pkey -in "$key_input" -pubout -out "$temp_dir/.verify-key.pem" >/dev/null 2>&1 \
	|| die "cannot write the verification key PEM"
"$openssl_bin" pkeyutl -verify -pubin -inkey "$temp_dir/.verify-key.pem" -rawin \
	-in "$temp_dir/manifest.json" -sigfile "$temp_dir/manifest.sig" >/dev/null 2>&1 \
	|| die "generated manifest signature did not verify"
rm -f -- "$temp_dir/.verify-key.pem"

chmod 0755 "$temp_dir"
chmod 0755 "$temp_dir/artifacts"
chmod 0644 "$temp_dir/manifest.json" "$temp_dir/manifest.sig"
mv -- "$temp_dir" "$output_dir"
temp_dir=
printf 'verification_key_hex=%s\n' "$verify_key_hex"
